import { StyleFn } from "..";

export const RangeSlider: StyleFn = (theme, mode) => {
  const { color, elevation, font, opacity, size: { spacing } } = theme;

  const baseTickStyle = {
    userSelect: "none",
    position: "absolute",
    transform: `translate(-50%, ${spacing[16]})`,
    color: color.text.neutral.default[mode],
    fontSize: font.size.small,
    lineHeight: font.size.small,
    "&:before": {
      content: "''",
      position: "absolute",
      width: '6px',
      height: '6px',
      borderRadius: "50%",
      backgroundColor: color.surface.componentonbackground.moderate[mode],
      top: `calc(-${spacing[16]} + 1px)`,
      left: "calc(50% - 3px)",
    },
  };

  const baseThumbStyle = {
    position: "absolute",
    width: spacing[16],
    height: spacing[16],
    borderRadius: "50%",
    border: `${spacing[2]} solid ${color.text.neutral.minimal[mode]}`,
    backgroundColor: color.surface.accent.hover[mode],
    transform: "translate(-50%, -25%)",
    boxShadow: elevation.level2,
    cursor: "pointer",
    "&:hover": {
      backgroundColor: color.surface.accent.hover[mode],
    },
    "&:focus, &:focus-visible": {
      outline: "none",
    },
    "&:focus-visible:before": {
      content: "''",
      position: "absolute",
      top: `calc(-${spacing[4]})`,
      left: `calc(-${spacing[4]})`,
      bottom: `calc(-${spacing[4]})`,
      right: `calc(-${spacing[4]})`,
      borderRadius: spacing[4],
      border: `${spacing[2]} solid ${color.border.accent.focus[mode]}`,
    },
  };

  return {
    root: {
      position: "relative",
      width: "100%",
      display: "block",
      boxSizing: "border-box",
      minHeight: spacing[16],
      "&:before": {
        content: "''",
        position: "absolute",
        width: "100%",
        height: spacing[8],
        borderRadius: spacing[4],
        backgroundColor: color.surface.componentonbackground.strong[mode],
      },
    },
    _vertical: {
      height: "100%",
      width: "unset",
      display: "inline-block",
      "&:before": {
        height: "100%",
        width: spacing[8],
      },
      "&$_withticks": {
        minWidth: spacing[32],
        minHeight: "unset",
      },
      "& $track": {
        width: spacing[8],
        height: "unset",
      },
      "& $tick": {
        transform: `translate(${spacing[16]}, -50%)`,
        "&:before": {
          top: spacing[4],
          left: `calc(-${spacing[16]} + 1px)`,
        },
      },
      "& $tick$tick_start": {
        transform: `translate(${spacing[16]}, -100%)`,
        "&:before": { top: "unset", bottom: 1 },
      },
      "& $tick$tick_end": {
        transform: `translate(${spacing[16]}, 0)`,
        "&:before": { top: 1 },
      },
      "& $thumb": {
        transform: "translate(-25%, -50%)",
      },
      "&$_large": {
        "& > $tick": {
          transform: `translate(${spacing[20]}, -50%)`,
          "&:before": {
            top: spacing[4],
            left: `calc(-${spacing[16]} + -3px)`,
          },
        },
        "& > $tick_start": {
          transform: `translate(${spacing[20]}, -100%)`,
          "&:before": { top: "unset", bottom: 1 },
        },
        "& > $tick$tick_end": {
          transform: `translate(${spacing[20]}, 0)`,
          "&:before": { top: 1, left: `calc(-${spacing[16]} - 3px)` },
        },
        "& > $thumb": {
          transform: "translate(-37%, -55%)",
        },
        "& $tooltip": {
          height: `calc(100% + ${spacing[20]})`,
          margin: -10,
        },
      },
    },
    _medium: {},
    _large: {
      "& > $tick": {
        extend: baseTickStyle,
        transform: `translate(-50%, calc(${spacing[20]} + 1px))`,
        "&:before": {
          extend: baseTickStyle["&:before"],
          top: `calc(-${spacing[20]})`,
        },
      },
      "& > $tick_start": {
        transform: `translate(14%, calc(${spacing[20]} + 1px))`,
        "&:before": { top: `calc(-${spacing[20]})` },
      },
      "& > $tick + $tick_end": {
        transform: `translate(-100%, calc(${spacing[20]} + 1px))`,
        "&:before": {
          left: "unset",
          right: 1,
          top: `calc(-${spacing[20]})`,
        },
      },
      "& > $tick + $tick_outside": {
        "&:before": { backgroundColor: color.text.neutral.strong[mode] },
      },
      "& > $thumb": {
        extend: baseThumbStyle,
        width: spacing[32],
        height: spacing[32],
        border: `${spacing[4]} solid ${color.text.neutral.minimal[mode]}`,
        transform: "translate(-50%, -40%)",
      },
    },
    _disabled: {
      cursor: "not-allowed",
      opacity: opacity.disabled,
      "& $track, & $thumb": {
        pointerEvents: "none",
      },
    },
    _withticks: {
      minHeight: spacing[32],
    },
    track: {
      position: "absolute",
      height: spacing[8],
      borderRadius: spacing[4],
      backgroundColor: color.surface.accent.hover[mode],
    },
    tick: { ...baseTickStyle },
    tick_outside: {
      "&:before": { backgroundColor: color.text.neutral.strong[mode] },
    },
    tick_start: {
      transform: `translate(0, ${spacing[16]})`,
      "&:before": { left: 1 },
    },
    tick_end: {
      transform: `translate(-100%, ${spacing[16]})`,
      "&:before": { left: "unset", right: 1 },
    },
    tick_current: {
      fontWeight: font.weight.bold,
    },
    thumb: { ...baseThumbStyle },
    tooltip: {
      height: `calc(100% + ${spacing[4]})`,
      margin: -2,
    },
  };
};

